 * For more details on building Java & JVM projects, please refer to https://docs.gradle.org/9.8.0/userguide/building_java_projects.html in the Gradle documentation.
 */

plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
    // id("com.gradleup.shadow") version "9.5.0"
    id("org.panteleyev.jpackageplugin") version "2.1.0"
}

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
}

dependencies {
    // Use JUnit Jupiter for testing.
    // testImplementation(libs.junit.jupiter)

    // testRuntimeOnly("org.junit.platform:junit-platform-launcher")

    // This dependency is used by the application.
    // implementation(libs.guava)
    implementation("io.qtjambi:qtjambi:6.12.0")
    runtimeOnly("io.qtjambi:qtjambi-native-linux-x64:6.12.0")
}

// Apply a specific Java toolchain to ease working on different environments.
// java {
//     toolchain {
//         languageVersion = JavaLanguageVersion.of(21)
//     }
// }

application {
    // Define the main class for the application.
    mainClass = "com.cwm.CrazyWaffleMidi.Main"
}

// tasks.named<Test>("test") {
//     // Use JUnit Platform for unit tests.
//     useJUnitPlatform()
// }

tasks.register("copyDependencies", Copy::class) {
    from(configurations.runtimeClasspath).into(layout.buildDirectory.dir("jmods"))
}

tasks.register("copyJar", Copy::class) {
    from(tasks.jar).into(layout.buildDirectory.dir("jmods"))
}

tasks.jpackage {
    dependsOn("build", "copyDependencies", "copyJar")

    appName = "CrazyWaffleMidi"
    appVersion = project.version.toString()
    appDescription = "Scuffed MIDI sequencer"
    vendor = "Crazy_Waffle_Man"
    runtimeImage = File(System.getProperty("java.home"))
    module = "com.cwm.CrazyWaffleMidi.Main"
    modulePaths.setFrom(tasks.named("copyJar"))
    destination = layout.buildDirectory.dir("dist")
    javaOptions = listOf("-Dfile.encoding=UTF-8")  

    type = ImageType.APP_IMAGE
}